"""Seating charts: students sorted by last name into rows."""

from rosterkit.errors import ProjectError


def _sort_key(pupil):
    return (pupil.last_name, pupil.first_name)


def _chunks(items, size):
    return [
        items[spot:spot + size]
        for spot in range(0, len(items), size)
    ]


def _row_line(rown, chunk):
    names = " | ".join(pupil.display_name for pupil in chunk)
    return f"Row {rown}: {names}"


# ---
def seat_rows(students, per_row):
    if per_row <= 0 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    chunks = _chunks(ordered, per_row)
    return [_row_line(*pair) for pair in enumerate(chunks, 1)]

